import { mapState } from 'vuex';

export default {
  name: 'home_service',
  cname: '悬浮按钮',
  configName: 'c_home_service',
  icon: '#iconzujian-xuanfuanniu',
  type: 2, // 0 基础组件 1 营销组件 2工具组件
  defaultName: 'customerService', // 外面匹配名称
  props: {
    index: {
      type: null,
      default: -1
    },
    num: {
      type: null
    }
  },
  computed: {
    ...mapState('admin/mobildConfig', ['defaultArray'])
  },
  watch: {
    pageData: {
      handler(nVal, oVal) {
        this.setConfig(nVal);
      },
      deep: true
    },
    num: {
      handler(nVal, oVal) {
        const data = this.$store.state.admin.mobildConfig.defaultArray[nVal];
        this.setConfig(data);
      },
      deep: true
    },
    'defaultArray': {
      handler(nVal, oVal) {
        const data = this.$store.state.admin.mobildConfig.defaultArray[this.num];
        this.setConfig(data);
      },
      deep: true
    }
  },
  data() {
    return {
      defaultConfig: {
		cname: '悬浮按钮',
        name: 'customerService',
        timestamp: this.num,
		isHide:false,
        setUp: {
          tabVal: 0
        },
		titleLeft:'按钮设置',
		titleRight:'位置设置',
		buttonConfig:{
			title:'按钮跳转',
			tabVal: 0,
			tabList: [
			  {
			    name: '页面链接'
			  },
			  {
			    name: '客服入口'
			  }
			]
		},
		locationConfig:{
			title:'展示位置',
			tabVal: 1,
			tabList: [
			  {
			    name: '左'
			  },
			  {
			    name: '右'
			  }
			]
		},
        logoConfig: {
          title: '建议：展示上传100*100px；',
          url: '',
		  link:''
        },
        // 页面间距
        topConfig: {
          title: '上下偏移',
          val: 0,
          min: 0
        }
      },
      imgUrl: '',
      pageData: {},
      mTop: 0,
	  positions: 1 //展示位置
    };
  },
  mounted() {
    this.$nextTick(() => {
      this.pageData = this.$store.state.admin.mobildConfig.defaultArray[this.num];
      this.setConfig(this.pageData);
    });
  },
  methods: {
    setConfig(data) {
      if (!data) return;
      if (data.topConfig) {
        this.mTop = data.topConfig.val;
        this.imgUrl = data.logoConfig.url;
		this.positions = data.locationConfig.tabVal;
      }
    }
  }
};
